step.params:
var power = parseFloat(value);
if (power === 0 || isNaN(power) || power > 100000) return -40; // Sem sinal / LOS
return ((power * 0.002) - 30).toFixed(2);

var lld = JSON.parse(value);
var map = {};

function getProprietaryIndex(snmpIndex) {
    if (snmpIndex >= 285212672) {
        return snmpIndex;
    }
    if (snmpIndex >= 268435456 && snmpIndex < 285212672) {
        var rem = snmpIndex - 268435456;
        var slot = Math.floor(rem / 65536);
        var port = Math.floor((rem % 65536) / 256) + 1;
        return 285278208 + (slot * 256) + port;
    }
    return null;
}

function parseStatus(val) {
    if (val === undefined || val === null) {
        return 1;
    }
    var str = val.toString().trim();
    if (str === '') {
        return 1;
    }
    if (/^\d+$/.test(str)) {
        return parseInt(str, 10);
    }
    var match = str.match(/\((\d+)\)/);
    if (match) {
        return parseInt(match[1], 10);
    }
    var lower = str.toLowerCase();
    if (lower === 'up' || lower === 'active') {
        return 1;
    }
    if (lower === 'down' || lower === 'inactive') {
        return 2;
    }
    return 1;
}

function parseCount(val) {
    if (val === undefined || val === null) {
        return 0;
    }
    var str = val.toString().trim();
    if (str === '') {
        return 0;
    }
    var match = str.match(/\d+/);
    if (match) {
        return parseInt(match[0], 10);
    }
    return 0;
}

for (var i = 0; i < lld.length; i++) {
    var item = lld[i];
    var snmpIndex = parseInt(item['{#SNMPINDEX}'], 10);
    if (isNaN(snmpIndex)) continue;

    var propIndex = getProprietaryIndex(snmpIndex);
    if (!propIndex) continue;

    var key = propIndex.toString();
    if (!map[key]) {
        map[key] = {
            '{#PROPRIETARYINDEX}': key,
            '{#SNMPINDEX}': snmpIndex.toString()
        };
    }

    for (var k in item) {
        if (item.hasOwnProperty(k)) {
            if (item[k] !== undefined && item[k] !== null) {
                if (k === '{#SNMPINDEX}') {
                    var currentSnmpIndex = parseInt(map[key]['{#SNMPINDEX}'], 10);
                    if (currentSnmpIndex >= 285212672 && snmpIndex < 285212672) {
                        map[key]['{#SNMPINDEX}'] = item[k];
                    }
                } else {
                    map[key][k] = item[k];
                }
            }
        }
    }
}

var result = [];
for (var propKey in map) {
    if (map.hasOwnProperty(propKey)) {
        var mergedItem = map[propKey];
        var ponName = mergedItem['{#PONNAME}'];

        if (ponName && (ponName.indexOf('gpon_') === 0 || ponName.indexOf('gpon-') === 0)) {
            var admin = parseStatus(mergedItem['{#PONADMIN}']);
            var oper = parseStatus(mergedItem['{#PONOPER}']);
            var auth = parseCount(mergedItem['{#ONUAUTH}']);

            mergedItem['{#PONADMIN}'] = admin.toString();
            mergedItem['{#PONOPER}'] = oper.toString();
            mergedItem['{#ONUAUTH}'] = auth.toString();
            mergedItem['{#PONDESC}'] = mergedItem['{#PONDESC}'] || '';

            if (admin === 1 && (oper === 1 || auth > 0)) {
                result.push(mergedItem);
            }
        }
    }
}

return JSON.stringify(result);

var power = parseFloat(value);
if (power === 0 || isNaN(power) || power > 100000) return -40;
return ((power * 0.002) - 30).toFixed(2);

var s = parseInt(value);
if (s === 2 || s === 10) return 10;
if (s === 3 || s === 100) return 100;
if (s === 4 || s === 1000) return 1000;
return s;
